// Get the infinite vertex to start propagation
typename Triangulation::Vertex_handle infinite_vertex = triangulation.infinite_vertex();

// Mark all faces as unlabeled initially
for (typename Triangulation::Finite_faces_iterator fit = triangulation.finite_faces_begin();
     fit != triangulation.finite_faces_end(); ++fit) {
    fit->info() = -1;  // -1 means unlabeled
}

// Create a queue for BFS propagation
std::queue<typename Triangulation::Face_handle> face_queue;

// Start with the infinite face's neighbors (exterior faces)
typename Triangulation::Face_circulator fc = triangulation.incident_faces(infinite_vertex);
typename Triangulation::Face_circulator fc_end = fc;
do {
    if (triangulation.is_infinite(fc)) continue;
    fc->info() = 0;  // 0 means exterior
    face_queue.push(fc);
} while (++fc != fc_end);

// BFS propagation using odd-even rule
while (!face_queue.empty()) {
    typename Triangulation::Face_handle current_face = face_queue.front();
    face_queue.pop();

    for (int i = 0; i < 3; ++i) {
        typename Triangulation::Face_handle neighbor = current_face->neighbor(i);
        if (triangulation.is_infinite(neighbor) || neighbor->info() != -1) continue;

        // Count constraint edges between current_face and neighbor
        int constraint_count = 0;
        for (int j = 0; j < 3; ++j) {
            if (current_face->is_constrained(j) && current_face->neighbor(j) == neighbor) {
                constraint_count++;
            }
        }

        // Odd-even rule: odd number of constraints means opposite label
        if (constraint_count % 2 == 1) {
            neighbor->info() = 1 - current_face->info();
        } else {
            neighbor->info() = current_face->info();
        }
        face_queue.push(neighbor);
    }
}

// Handle infinite faces (mark as exterior)
for (typename Triangulation::All_faces_iterator fit = triangulation.all_faces_begin();
     fit != triangulation.all_faces_end(); ++fit) {
    if (triangulation.is_infinite(fit)) {
        fit->info() = 0;
    }
}
// END_CODE

